-- unsubscribe_digests (WP-35; messaging-47..52,55,58,v15,v16, database-46,86): saved_searches (F6 digests), reminders (F5
-- nudges), mail_opt_outs (opt-outs kept by address hash), the contact form's dedupe key, and an opted-out-until-consent
-- default for profiles.mail_opt_out.
-- Generated by drizzle-kit for the tables, columns, indexes and checks. HAND EDITS (re-apply after renumbering; last renumbered 0018 -> 0022 at the merge with WP-24 and WP-26):
--   1. The functions below come first: saved_searches_filters_ck calls saved_search_filters_valid, a pure validator
--      granted to PUBLIC like preferences_valid (0007); saved_search_zone, user_local_day and saved_search_next_due are
--      the one definition of "the person's day" and of 08:00 local, with an unknown zone read as UTC.
--   2. After the tables: saved_searches_guard (the limit of 10 under the profiles lock, next_digest_at, updated_at) and
--      profiles_timezone_digest (a time-zone change moves the due times), both with their triggers.
--   3. Backfills at the end: every existing profile is opted out of the four mail kinds (nothing has ever been sent, so
--      nobody has consented) and gets the default "My matches" search (B-4). Both are no-ops on a re-run. The backfill
--      holds a lock on profiles while it runs; its cost is one saved_search_next_due call per profile (a cheap zone
--      probe, no catalog scan), so it is seconds at 10,000 profiles.
-- Everything here is expand-only: the old api never reads or writes these columns and tables, and the new default of
-- mail_opt_out only changes rows the old code inserts during the deploy window (they come out opted out, the safe way).
-- The grants of the three new tables are in ops/provision-roles.sql.
-- saved_search_filters: only the four known keys, each of the right type, so no row can make the digest query fail.
CREATE FUNCTION saved_search_filters_valid(f jsonb) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE AS $$
BEGIN
  IF f IS NULL OR jsonb_typeof(f) IS DISTINCT FROM 'object' OR octet_length(f::text) > 4000 THEN RETURN false; END IF;
  IF f - ARRAY['minScore','roles','companies','remoteOnly'] <> '{}'::jsonb THEN RETURN false; END IF;
  IF f ? 'minScore' AND NOT jsonb_int_between(f -> 'minScore', 0, 100) THEN RETURN false; END IF;
  IF f ? 'roles' AND NOT jsonb_text_array_ok(f -> 'roles', 0, 10, 2, 80) THEN RETURN false; END IF;
  IF f ? 'companies' AND NOT jsonb_text_array_ok(f -> 'companies', 0, 20, 1, 120) THEN RETURN false; END IF;
  IF f ? 'remoteOnly' AND jsonb_typeof(f -> 'remoteOnly') IS DISTINCT FROM 'boolean' THEN RETURN false; END IF;
  RETURN true;
END $$;--> statement-breakpoint
-- A usable zone name: the given one, or UTC when it is null or unknown. Probing the zone is a cheap lookup that raises
-- invalid_parameter_value for an unknown name (profiles.timezone has no check of its own, only profiles_guard on change).
CREATE FUNCTION saved_search_zone(p_tz text) RETURNS text
LANGUAGE plpgsql STABLE AS $$
DECLARE zone text := coalesce(p_tz, 'UTC');
BEGIN
  PERFORM now() AT TIME ZONE zone;
  RETURN zone;
EXCEPTION WHEN invalid_parameter_value THEN
  RETURN 'UTC';
END $$;--> statement-breakpoint
-- The person's calendar day of an instant, as YYYY-MM-DD: the digest's entity date.
CREATE FUNCTION user_local_day(p_ts timestamptz, p_tz text) RETURNS text
LANGUAGE sql STABLE AS $$
SELECT to_char(p_ts AT TIME ZONE saved_search_zone(p_tz), 'YYYY-MM-DD')
$$;--> statement-breakpoint
-- The first 08:00 local time after `p_after` (weekly: the first Monday 08:00), as an instant. An unknown zone falls back to UTC.
CREATE FUNCTION saved_search_next_due(p_frequency text, p_tz text, p_after timestamptz) RETURNS timestamptz
LANGUAGE plpgsql STABLE AS $$
DECLARE
  zone text := saved_search_zone(p_tz);
  local_start timestamp;
  due timestamptz;
BEGIN
  IF p_frequency = 'weekly' THEN
    local_start := date_trunc('week', p_after AT TIME ZONE zone) + interval '8 hours';
    due := local_start AT TIME ZONE zone;
    IF due <= p_after THEN due := (local_start + interval '7 days') AT TIME ZONE zone; END IF;
  ELSE
    local_start := date_trunc('day', p_after AT TIME ZONE zone) + interval '8 hours';
    due := local_start AT TIME ZONE zone;
    IF due <= p_after THEN due := (local_start + interval '1 day') AT TIME ZONE zone; END IF;
  END IF;
  RETURN due;
END $$;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION saved_search_filters_valid(jsonb) TO PUBLIC;--> statement-breakpoint
