-- The limit of 10 per user is counted under the profiles row lock (identity rule I1), so two racing inserts cannot both
-- pass; the api maps saved_searches_limit_ck to 409 limit_reached. next_digest_at is computed on insert and when the
-- frequency changes; the claim (jobs/digest.ts) sets it itself.
CREATE FUNCTION saved_searches_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM 1 FROM profiles WHERE user_id = NEW.user_id FOR NO KEY UPDATE;
    IF (SELECT count(*) FROM saved_searches WHERE user_id = NEW.user_id) >= 10 THEN
      RAISE EXCEPTION 'a user has at most 10 saved searches' USING ERRCODE = '23514', CONSTRAINT = 'saved_searches_limit_ck';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' OR NEW.frequency IS DISTINCT FROM OLD.frequency THEN
    NEW.next_digest_at := CASE WHEN NEW.frequency = 'off' THEN NULL
      ELSE saved_search_next_due(NEW.frequency, (SELECT p.timezone FROM profiles p WHERE p.user_id = NEW.user_id), now()) END;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;--> statement-breakpoint
CREATE TRIGGER saved_searches_guard_biu BEFORE INSERT OR UPDATE ON saved_searches
  FOR EACH ROW EXECUTE FUNCTION saved_searches_guard();--> statement-breakpoint
CREATE FUNCTION profiles_timezone_digest() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  UPDATE saved_searches SET next_digest_at = saved_search_next_due(frequency, NEW.timezone, now())
   WHERE user_id = NEW.user_id AND frequency <> 'off';
  RETURN NULL;
END $$;--> statement-breakpoint
CREATE TRIGGER profiles_timezone_digest_au AFTER UPDATE OF timezone ON profiles
  FOR EACH ROW WHEN (OLD.timezone IS DISTINCT FROM NEW.timezone) EXECUTE FUNCTION profiles_timezone_digest();--> statement-breakpoint

-- Backfills (re-runnable). No digest, report or summary has ever been sent, so every existing profile is opted out of
-- all four kinds until the person (or the owner's consent default, owner-actions/WP-35.md) says otherwise.
UPDATE profiles SET mail_opt_out = ARRAY['digest','outcome_report','autopilot_summary','reminders']::text[] WHERE mail_opt_out = '{}'::text[];--> statement-breakpoint
